from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    for op in ops:
        kind, t = op[0], op[1]
        if kind == 'put':
            key, value = op[2], op[3]
            # check if key present and not expired
            if key in cache:
                _, wt = cache[key]
                if t - wt < ttl:
                    # present, update value and time, move to most recently used
                    del cache[key]
                    cache[key] = (value, t)
                else:
                    # expired, treat as absent -> remove first
                    del cache[key]
                    # need capacity check
                    if len(cache) >= capacity:
                        cache.popitem(last=False)
                    cache[key] = (value, t)
            else:
                # absent
                if len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[key] = (value, t)
        elif kind == 'get':
            key = op[2]
            if key in cache:
                value, wt = cache[key]
                if t - wt < ttl:
                    results.append(value)
                    del cache[key]
                    cache[key] = (value, wt)
                else:
                    del cache[key]
                    results.append(-1)
            else:
                results.append(-1)

    return results

